    public function forward(\WP_REST_Request $request): \WP_REST_Response
    {
        $gate=$this->versionResponse($request);if($gate instanceof \WP_REST_Response)return $gate;$session=$this->authenticateContext($request);if($session instanceof \WP_REST_Response)return $session;$limit=$this->rateLimits->check('forward',(string)$session['account_id'].':'.(string)$session['site_id'],120,60);if(!$limit['allowed'])return $this->rateLimited($limit['retry_after']);$path=$this->policy->validatePath((string)$request->get_param('path'));if($path===null)return new \WP_REST_Response(['code'=>'operation_not_allowed'],404);$method=strtoupper($request->get_method());$key=trim((string)$request->get_header('Idempotency-Key'));if($key!==''&&(strlen($key)>190||!preg_match('/^[A-Za-z0-9._:-]{1,190}$/',$key)))return new \WP_REST_Response(['code'=>'invalid_idempotency_key'],400);if(!$this->policy->validateMethod($method,$key!==''))return new \WP_REST_Response(['code'=>'invalid_mutation_request'],400);$base=$this->policy->resolveSiteUrl($session['site']['canonical_url']);if($base===null)return new \WP_REST_Response(['code'=>'invalid_site_identity'],403);$credentials=$this->credentials($request,$path);if($credentials===null)return new \WP_REST_Response(['code'=>'missing_customer_credentials'],400);$query=$request->get_query_params();unset($query['path']);$rawBody=(string)$request->get_body();$contentType=(string)$request->get_header('content-type');$maxBody=str_starts_with($path,'/wp-json/wp/v2/media')?self::MAX_MEDIA_BYTES:self::MAX_BODY_BYTES;if(strlen($rawBody)>$maxBody)return new \WP_REST_Response(['code'=>'request_body_too_large','max_bytes'=>$maxBody],413);$fingerprint=$this->idempotency->fingerprint($method,$path,$query,$rawBody);$operationId='';
