    private function authenticateContext(\WP_REST_Request $request): array|\WP_REST_Response{$session=$this->sessions->authenticate((string)$request->get_header('X-WooGit-Session'));if($session===null)return new \WP_REST_Response(['code'=>'invalid_session'],401);if(($session['scope']??'')!==SessionService::SCOPE_OPERATIONAL)return new \WP_REST_Response(['code'=>'insufficient_session_scope'],403);$account=$this->accounts->get((int)$session['account_id']);if(!$account)return new \WP_REST_Response(['code'=>'account_inactive'],403);$site=$this->sites->getOwned((int)$session['account_id'],(int)$session['site_id']);if(!$site)return new \WP_REST_Response(['code'=>'site_not_owned'],403);if(!$this->entitlements->isAllowed((int)$session['account_id'],(int)$session['site_id'],'commerce'))return new \WP_REST_Response(['code'=>'not_entitled'],403);$expires=$this->entitlements->getExpiresAt((int)$session['account_id'],(int)$session['site_id']);if($expires!==null)$this->sessions->reconcileOperational((int)$session['account_id'],(int)$session['site_id'],$expires);$session['site']=$site;return $session;}
